cd /app/categorizationapp/categorizationapp && python3 - <<'EOF'
import re,os,sys
sys.path.insert(0,'.')
# load constants manually
consts={}
for f in ['UtilityScripts/BankRegexConstants.py','UtilityScripts/RegexConstants.py']:
    src=open(f).read()
    for m in re.finditer(r'^([A-Z_0-9]+)\s*=\s*(".*?")\s*$', src, re.M):
        try: consts[m.group(1)]=eval(m.group(2))
        except: pass

import glob
def ngroups(p):
    try:
        return re.compile(p).groups
    except Exception as e:
        return None

for f in sorted(glob.glob('BankScripts/*.py'))+glob.glob('UtilityScripts/*.py'):
    for i,line in enumerate(open(f),1):
        for m in re.finditer(r'py_extract\(\s*[^,]+,\s*(?:pat=)?(.+?),\s*index=(\d+)\)', line):
            pat_expr, idx = m.group(1).strip(), int(m.group(2))
            if pat_expr.startswith('"') and pat_expr.endswith('"'):
                try: pat=eval(pat_expr)
                except: continue
            elif pat_expr in consts:
                pat=consts[pat_expr]
            else:
                continue
            g=ngroups(pat)
            if g is None: 
                print("BADRE",f,i,pat_expr); continue
            if idx>=max(g,1):
                print(f"{f}:{i} idx={idx} groups={g} pat={pat_expr}={pat!r}")
EOF

